  static Material Mat(string name, Shader sh, Color c) {
    Directory.CreateDirectory("Assets/Resources/Mats"); string p = $"Assets/Resources/Mats/{name}.mat";
    var m = AssetDatabase.LoadAssetAtPath<Material>(p); if (m == null) { m = new Material(sh); AssetDatabase.CreateAsset(m, p); }
    m.shader = sh; if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c); EditorUtility.SetDirty(m); return m; }
  public static void Setup() {
    // URP, mobile-lean
    Directory.CreateDirectory("Assets/Settings");
    var rd = AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Settings/MobileRenderer.asset");
    if (rd == null) { rd = ScriptableObject.CreateInstance<UniversalRendererData>(); AssetDatabase.CreateAsset(rd, "Assets/Settings/MobileRenderer.asset"); }
    var urp = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/MobileURP.asset");
    if (urp == null) { urp = UniversalRenderPipelineAsset.Create(rd); AssetDatabase.CreateAsset(urp, "Assets/Settings/MobileURP.asset"); }
    urp.supportsHDR = false; urp.msaaSampleCount = 2; urp.renderScale = 1f; urp.shadowDistance = 70; urp.shadowCascadeCount = 1; { var so = new SerializedObject(urp); var sp = so.FindProperty("m_SoftShadowsSupported"); if (sp != null) sp.intValue = 1; var mr = so.FindProperty("m_MainLightShadowmapResolution"); if (mr != null) mr.intValue = 2048; so.ApplyModifiedPropertiesWithoutUndo(); } urp.supportsCameraDepthTexture = false; urp.supportsCameraOpaqueTexture = false;
    EditorUtility.SetDirty(urp);
    GraphicsSettings.defaultRenderPipeline = urp;
    for (int i = 0; i < QualitySettings.names.Length; i++) { QualitySettings.SetQualityLevel(i, false); QualitySettings.renderPipeline = urp; }
    // materials (kept in Resources so they ship)
    var lit = Shader.Find("Universal Render Pipeline/Simple Lit");
    Mat("Hull", lit, new Color(0.55f, 0.36f, 0.22f)); Mat("Mast", lit, new Color(0.30f, 0.20f, 0.12f));
    var sail = Mat("Sail", lit, new Color(0.80f, 0.72f, 0.58f)); sail.SetFloat("_Cull", 0); sail.doubleSidedGI = true;
    Mat("Island", lit, new Color(0.62f, 0.55f, 0.40f));
    ShipAssets(lit);
    { var tp = "Assets/Resources/Mats/fire_dot.png"; if (!File.Exists(tp)) { var t = new Texture2D(64, 64); for (int y = 0; y < 64; y++) for (int x = 0; x < 64; x++) { float d = Mathf.Clamp01(1 - new Vector2(x - 31.5f, y - 31.5f).magnitude / 32f); t.SetPixel(x, y, new Color(1, 1, 1, d * d)); } File.WriteAllBytes(tp, t.EncodeToPNG()); AssetDatabase.ImportAsset(tp); }
      AssetDatabase.ImportAsset("Assets/Resources/Shaders/FireAdd.shader"); var fm = Mat("Fire", Shader.Find("Galeborne/FireAdd"), Color.white); fm.SetTexture("_BaseMap", AssetDatabase.LoadAssetAtPath<Texture2D>(tp)); fm.SetFloat("_Surface", 1); fm.SetFloat("_Blend", 2); fm.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.SrcAlpha); fm.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.One); fm.SetFloat("_ZWrite", 0); fm.EnableKeyword("_SURFACE_TYPE_TRANSPARENT"); fm.renderQueue = 3000; EditorUtility.SetDirty(fm); } /* additive fire particles */
    { var tp2 = "Assets/Resources/Mats/fire_tongue.png"; if (!File.Exists(tp2)) { var t = new Texture2D(64, 128); for (int y = 0; y < 128; y++) for (int x = 0; x < 64; x++) { float fy = y / 127f, fx = (x - 31.5f) / 32f; float wdt = Mathf.Sin(Mathf.Clamp01(fy * 1.25f) * Mathf.PI) * (1 - fy * 0.55f) * 0.95f + 0.02f; float n = Mathf.PerlinNoise(x * 0.12f, y * 0.07f) * 0.35f; float d = Mathf.Clamp01(1 - Mathf.Abs(fx) / Mathf.Max(0.02f, wdt - n * fy)); float al = Mathf.Pow(d, 1.6f) * Mathf.Clamp01((1 - fy) * 1.6f) * Mathf.Clamp01(fy * 6); t.SetPixel(x, y, new Color(1, 1, 1, al)); } File.WriteAllBytes(tp2, t.EncodeToPNG()); AssetDatabase.ImportAsset(tp2); }
      var ft = Mat("FireTongue", Shader.Find("Galeborne/FireAdd"), Color.white); ft.SetTexture("_BaseMap", AssetDatabase.LoadAssetAtPath<Texture2D>(tp2)); ft.SetFloat("_Boost", 1.25f); ft.renderQueue = 3001; EditorUtility.SetDirty(ft);
      AssetDatabase.ImportAsset("Assets/Resources/Shaders/FireCut.shader"); var fcut = Mat("FireCut", Shader.Find("Galeborne/FireCut"), Color.white); fcut.SetTexture("_BaseMap", AssetDatabase.LoadAssetAtPath<Texture2D>(tp2)); fcut.SetFloat("_Cut", 0.42f); fcut.renderQueue = 2450; EditorUtility.SetDirty(fcut); /* v0.6g4: opaque, sharp-edged flames */
      AssetDatabase.ImportAsset("Assets/Resources/Shaders/FireAlpha.shader"); var smk = Mat("Smoke", Shader.Find("Galeborne/FireAlpha"), Color.white); smk.SetTexture("_BaseMap", AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/Mats/fire_dot.png")); smk.SetFloat("_Boost", 1f); smk.renderQueue = 3000; EditorUtility.SetDirty(smk); } /* v0.6g flame tongues + smoke */
    { var litS = Shader.Find("Universal Render Pipeline/Lit"); foreach (var (n, c) in new[] { ("Turban", new Color(0.11f, 0.16f, 0.4f)), ("F_EyeW", new Color(0.82f, 0.78f, 0.7f)), ("Sash", new Color(0.9f, 0.06f, 0.04f)), ("F_Skin", new Color(0.72f, 0.48f, 0.33f)), ("F_Kurta", new Color(0.93f, 0.9f, 0.82f)), ("F_Shirt", new Color(0.86f, 0.8f, 0.68f)), ("F_Trousers", new Color(0.42f, 0.41f, 0.4f)), ("F_Vest", new Color(0.36f, 0.22f, 0.12f)), ("F_Leather", new Color(0.45f, 0.27f, 0.14f)), ("F_Boot", new Color(0.22f, 0.15f, 0.1f)), ("F_Beard", new Color(0.2f, 0.13f, 0.08f)), ("F_Hair", new Color(0.12f, 0.09f, 0.07f)), ("F_Eye", new Color(0.08f, 0.06f, 0.05f)), ("F_Lip", new Color(0.55f, 0.3f, 0.25f)), ("F_Steel", new Color(0.78f, 0.8f, 0.84f)), ("F_Gold", new Color(0.8f, 0.62f, 0.25f)) }) { var tm = Mat(n, litS, c); tm.EnableKeyword("_EMISSION"); tm.SetColor("_EmissionColor", c * (n.StartsWith("F_") ? 0.18f : n == "Turban" ? 0.3f : 0.55f)); tm.SetFloat("_Smoothness", 0.15f); tm.globalIlluminationFlags = MaterialGlobalIlluminationFlags.None; EditorUtility.SetDirty(tm); } } /* duel: Hasan's blue turban, raider's red sash */
    { var ol = Mat("Outline", Shader.Find("Universal Render Pipeline/Unlit"), new Color(1f, 0.74f, 0.32f)); if (ol.HasProperty("_Cull")) ol.SetFloat("_Cull", 1); EditorUtility.SetDirty(ol); }
    foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/Resources/TownTex" })) { var ti = (TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid)); var an = ti.GetPlatformTextureSettings("Android"); if (!ti.isReadable || ti.textureCompression != TextureImporterCompression.Uncompressed || !an.overridden || an.maxTextureSize != 128) { ti.isReadable = true; ti.textureCompression = TextureImporterCompression.Uncompressed; ti.mipmapEnabled = false; an.overridden = true; an.maxTextureSize = 128; an.format = TextureImporterFormat.RGB24; ti.SetPlatformTextureSettings(an); ti.SaveAndReimport(); } } /* 128 px RGB24 on Android: read once into the atlas, keeps the APK under 24 MB */
    foreach (var f in new[] { "v06_settings", "v06_market_events_data", "v06_ambush_data", "v06_events_content" }) { var src = "/workspace/galeborne/design/" + f + ".json"; if (File.Exists(src)) { Directory.CreateDirectory("Assets/Resources/Design"); File.Copy(src, "Assets/Resources/Design/" + f + ".txt", true); } } /* design data loaded straight from the design folder at build time */
    AssetDatabase.Refresh();
    Mat("Water", Shader.Find("Galeborne/Water"), Color.white); Mat("Sky", Shader.Find("Galeborne/Sky"), Color.white);
    // scene
    Directory.CreateDirectory("Assets/Scenes");
    var sc = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
    var cam = new GameObject("Main Camera").AddComponent<Camera>(); cam.tag = "MainCamera"; cam.gameObject.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing = false;
    new GameObject("Galeborne").AddComponent<Game>();
    EditorSceneManager.SaveScene(sc, Scene);
    EditorBuildSettings.scenes = new[] { new EditorBuildSettingsScene(Scene, true) };
    // player
    PlayerSettings.companyName = "Sannan Nasir"; PlayerSettings.productName = "Galeborne"; PlayerSettings.bundleVersion = "0.4";
    PlayerSettings.defaultInterfaceOrientation = UIOrientation.Portrait;
    PlayerSettings.SetApplicationIdentifier(UnityEditor.Build.NamedBuildTarget.Android, "com.sannan.galeborne");
    PlayerSettings.Android.minSdkVersion = AndroidSdkVersions.AndroidApiLevel26;
    PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android, ScriptingImplementation.IL2CPP);
    PlayerSettings.Android.targetArchitectures = AndroidArchitecture.ARM64;
    PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Standalone, ScriptingImplementation.Mono2x);
    PlayerSettings.defaultScreenWidth = 540; PlayerSettings.defaultScreenHeight = 960; PlayerSettings.fullScreenMode = FullScreenMode.Windowed; PlayerSettings.resizableWindow = true;
    Application.targetFrameRate = 30;
    AssetDatabase.SaveAssets(); Debug.Log("GB SETUP OK");
  }
  static Texture2D WriteTex(string path, Color[] px, int n, bool normal, bool alpha = false) {
    var t = new Texture2D(n, n, TextureFormat.RGBA32, false); t.SetPixels(px); t.Apply(); File.WriteAllBytes(path, t.EncodeToPNG()); AssetDatabase.ImportAsset(path);
    var ti = (TextureImporter)AssetImporter.GetAtPath(path); ti.textureType = normal ? TextureImporterType.NormalMap : TextureImporterType.Default; ti.maxTextureSize = 1024; ti.mipmapEnabled = true;
    ti.alphaIsTransparency = alpha; ti.SaveAndReimport(); return AssetDatabase.LoadAssetAtPath<Texture2D>(path); }
  static void ShipAssets(Shader lit) {
    Directory.CreateDirectory("Assets/Resources/Ship");
    foreach (var pirate in new[] { false, true }) { string k = pirate ? "pirate" : "hasan"; string ap = $"Assets/Resources/Ship/atlas_{k}.png", np = $"Assets/Resources/Ship/normal_{k}.png";
      Texture2D al = AssetDatabase.LoadAssetAtPath<Texture2D>(ap), nm = AssetDatabase.LoadAssetAtPath<Texture2D>(np);
      if (al == null || nm == null) { ShipArt.Paint(pirate, out var a, out var h); al = WriteTex(ap, a, ShipArt.N, false); nm = WriteTex(np, ShipArt.NormalFromHeight(h, 6f), ShipArt.N, true); }
      var m = Mat(pirate ? "ShipPirate" : "ShipHasan", lit, Color.white); m.SetTexture("_BaseMap", al); m.mainTexture = al; m.SetTexture("_BumpMap", nm); m.EnableKeyword("_NORMALMAP");
      m.SetFloat("_Cull", 2); m.SetFloat("_Smoothness", 0.15f); EditorUtility.SetDirty(m); }
    string fp = "Assets/Resources/Ship/foam.png"; var ft = AssetDatabase.LoadAssetAtPath<Texture2D>(fp); if (ft == null) ft = WriteTex(fp, ShipArt.Foam(128), 128, false, true);
    var fm = Mat("Foam", Shader.Find("Galeborne/Foam"), Color.white); fm.SetTexture("_MainTex", ft); EditorUtility.SetDirty(fm);
  }
  public static void BuildAndroid() {
    Setup();
    EditorUserBuildSettings.buildAppBundle = false; PlayerSettings.Android.useCustomKeystore = false; // Unity debug keystore => signed debug APK
    var r = BuildPipeline.BuildPlayer(new BuildPlayerOptions { scenes = new[] { Scene }, locationPathName = "/workspace/Galeborne_v0.4.apk", target = BuildTarget.Android, options = BuildOptions.Development });
    Debug.Log($"GB ANDROID {r.summary.result} size={r.summary.totalSize} errors={r.summary.totalErrors}"); if (r.summary.result != BuildResult.Succeeded) EditorApplication.Exit(1);
  }
