  /// full-texture variant: undo the Android downgrades (ship normals 512, port backdrops/chart ASTC 8x8-10x10 + crunch, town textures 128 px)
  static void HQPass() {
    void Full(string folder, string filter, bool readable) { foreach (var guid in AssetDatabase.FindAssets(filter + " t:Texture2D", new[] { folder })) { var ti = (TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid));
      ti.maxTextureSize = 2048; ti.crunchedCompression = false; ti.compressionQuality = 100; if (readable) { ti.isReadable = true; ti.textureCompression = TextureImporterCompression.Uncompressed; }
      var a = ti.GetPlatformTextureSettings("Android"); a.overridden = true; a.maxTextureSize = 2048; a.crunchedCompression = false; a.format = readable ? TextureImporterFormat.RGB24 : TextureImporterFormat.ASTC_4x4; ti.SetPlatformTextureSettings(a); ti.SaveAndReimport(); } }
    Full("Assets/Resources/Ship", "normal_", false); Full("Assets/Resources/Ship", "atlas_", false); Full("Assets/Resources/Art", "", false); Full("Assets/Resources/TownTex", "", true);
    Debug.Log("GB HQ textures applied"); }
