  /// mid variant for a 25 MB attachment: chart + town textures full, ship normals 512, port backdrops/ship colour compressed
  static void MQPass() {
    /* v0.6k3: Kenney lateen needs readable mesh for double-sided fix */
    var kenney = "Assets/Resources/Ship/Kenney/hasan_dhow_kenney.fbx";
    var mi = AssetImporter.GetAtPath(kenney) as ModelImporter;
    if (mi != null && !mi.isReadable) { mi.isReadable = true; mi.SaveAndReimport(); }

    void Set(string folder, string filter, Func<string, bool> pick, int max, TextureImporterFormat f, bool readable) { foreach (var guid in AssetDatabase.FindAssets(filter + " t:Texture2D", new[] { folder })) { var ti = (TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid)); if (!pick(ti.assetPath)) continue;
      ti.maxTextureSize = Math.Max(max, 1024); ti.crunchedCompression = false; ti.compressionQuality = 100; if (readable) { ti.isReadable = true; ti.textureCompression = TextureImporterCompression.Uncompressed; }
      var a = ti.GetPlatformTextureSettings("Android"); a.overridden = true; a.maxTextureSize = max; a.crunchedCompression = false; a.format = f; ti.SetPlatformTextureSettings(a); ti.SaveAndReimport(); } }
    Set("Assets/Resources/Art", "chart", p => p.Contains("chart"), 2048, TextureImporterFormat.ASTC_4x4, false);
    Set("Assets/Resources/TownTex", "", p => true, 2048, TextureImporterFormat.RGB24, true);
    Set("Assets/Resources/Ship", "normal_", p => true, 512, TextureImporterFormat.ASTC_8x8, false);
    Set("Assets/Resources/Art", "port_", p => true, 1024, TextureImporterFormat.ASTC_12x12, false);
    Set("Assets/Resources/Ship", "atlas_", p => true, 2048, TextureImporterFormat.ASTC_8x8, false);
    Set("Assets/Resources/Art/Portraits", "", p => true, 512, TextureImporterFormat.ASTC_6x6, false); /* v0.6h Yusuf/Farida portraits */
    Set("Assets/Resources/Art", "alley_debal", p => p.Contains("alley_debal"), 1024, TextureImporterFormat.ASTC_8x8, false);
    Set("Assets/Resources/Art", "alley_muscat", p => p.Contains("alley_muscat"), 1024, TextureImporterFormat.ASTC_8x8, false); /* v0.6h4 */
    Set("Assets/Resources/Art", "coin_spill", p => p.Contains("coin_spill"), 512, TextureImporterFormat.ASTC_6x6, false);
    Set("Assets/Resources/Art", "ui_parch", p => p.Contains("ui_parch"), 512, TextureImporterFormat.ASTC_6x6, false); /* v0.6g3 parchment panels */
    Set("Assets/Resources/Art", "ui_teak", p => p.Contains("ui_teak"), 1024, TextureImporterFormat.ASTC_6x6, false); /* v0.6i teak 9-slice panel */
    Set("Assets/Resources/Art", "ui_setsail", p => p.Contains("ui_setsail"), 1024, TextureImporterFormat.ASTC_6x6, false);
    Set("Assets/Resources/Art", "ui_map_ship", p => p.Contains("ui_map_ship"), 512, TextureImporterFormat.ASTC_6x6, false);
    Debug.Log("GB MQ textures applied"); }
