    foreach (var guid in AssetDatabase.FindAssets("port_ t:Texture2D", new[] { "Assets/Resources/Art" })) { var ti = (TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid)); var an = ti.GetPlatformTextureSettings("Android"); if (an.format != TextureImporterFormat.ASTC_10x10) { an.overridden = true; an.maxTextureSize = Math.Max(an.maxTextureSize, 1024); an.format = TextureImporterFormat.ASTC_8x8; ti.SetPlatformTextureSettings(an); ti.SaveAndReimport(); } } /* port backdrops ASTC 8x8 */
    foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/Resources/Keepers", "Assets/Resources/GoodsIcons" })) {
      var ti = (TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid)); bool face = ti.assetPath.Contains("Keepers");
      ti.mipmapEnabled = false; ti.maxTextureSize = face ? 256 : 128; var a = ti.GetPlatformTextureSettings("Android"); a.overridden = true; a.maxTextureSize = ti.maxTextureSize; a.format = TextureImporterFormat.ASTC_6x6; ti.SetPlatformTextureSettings(a); ti.SaveAndReimport(); }
    foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/Resources/Art" })) {
      var ti = (TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid));
      ti.mipmapEnabled = false; ti.maxTextureSize = 1280; ti.crunchedCompression = true; ti.compressionQuality = 50;
      var a = ti.GetPlatformTextureSettings("Android"); a.overridden = true; a.maxTextureSize = 1280; a.format = (ti.assetPath.Contains("chart") || ti.assetPath.Contains("port_")) ? TextureImporterFormat.ASTC_10x10 : TextureImporterFormat.ASTC_6x6; ti.SetPlatformTextureSettings(a); ti.SaveAndReimport(); }
